         s(51) = + g1p(ix+0)*g8p(iy+0)*g6p(iz+0)
         s(52) = + g0p(ix+0)*g9p(iy+0)*g6p(iz+0)
         s(53) = + g0p(ix+0)*g8p(iy+0)*g7p(iz+0)
         s(54) = + g7p(ix+0)*g0p(iy+0)*g8p(iz+0)
         s(55) = + g6p(ix+0)*g1p(iy+0)*g8p(iz+0)
         s(56) = + g6p(ix+0)*g0p(iy+0)*g9p(iz+0)
         s(57) = + g5p(ix+0)*g2p(iy+0)*g8p(iz+0)
         s(58) = + g4p(ix+0)*g3p(iy+0)*g8p(iz+0)
         s(59) = + g4p(ix+0)*g2p(iy+0)*g9p(iz+0)
         s(60) = + g5p(ix+0)*g0p(iy+0)*g10p(iz+0)
         s(61) = + g4p(ix+0)*g1p(iy+0)*g10p(iz+0)
         s(62) = + g4p(ix+0)*g0p(iy+0)*g11p(iz+0)
         s(63) = + g3p(ix+0)*g4p(iy+0)*g8p(iz+0)
         s(64) = + g2p(ix+0)*g5p(iy+0)*g8p(iz+0)
         s(65) = + g2p(ix+0)*g4p(iy+0)*g9p(iz+0)
         s(66) = + g1p(ix+0)*g6p(iy+0)*g8p(iz+0)
         s(67) = + g0p(ix+0)*g7p(iy+0)*g8p(iz+0)
         s(68) = + g0p(ix+0)*g6p(iy+0)*g9p(iz+0)
         s(69) = + g1p(ix+0)*g4p(iy+0)*g10p(iz+0)
         s(70) = + g0p(ix+0)*g5p(iy+0)*g10p(iz+0)
         s(71) = + g0p(ix+0)*g4p(iy+0)*g11p(iz+0)
         s(72) = + g3p(ix+0)*g0p(iy+0)*g12p(iz+0)
         s(73) = + g2p(ix+0)*g1p(iy+0)*g12p(iz+0)
         s(74) = + g2p(ix+0)*g0p(iy+0)*g13p(iz+0)
         s(75) = + g1p(ix+0)*g2p(iy+0)*g12p(iz+0)
         s(76) = + g0p(ix+0)*g3p(iy+0)*g12p(iz+0)
         s(77) = + g0p(ix+0)*g2p(iy+0)*g13p(iz+0)
         s(78) = + g1p(ix+0)*g0p(iy+0)*g14p(iz+0)
         s(79) = + g0p(ix+0)*g1p(iy+0)*g14p(iz+0)
         s(80) = + g0p(ix+0)*g0p(iy+0)*g15p(iz+0)
         if (gout_empty /= 0) then
            gout(n*9+0) = - s(0) - s(4) - s(8)
            gout(n*9+1) = - s(27) - s(31) - s(35)
            gout(n*9+2) = - s(54) - s(58) - s(62)
            gout(n*9+3) = - s(9) - s(13) - s(17)
            gout(n*9+4) = - s(36) - s(40) - s(44)
            gout(n*9+5) = - s(63) - s(67) - s(71)
            gout(n*9+6) = - s(18) - s(22) - s(26)
            gout(n*9+7) = - s(45) - s(49) - s(53)
            gout(n*9+8) = - s(72) - s(76) - s(80)
         else
            gout(n*9+0) = gout(n*9+0) + ( - s(0) - s(4) - s(8) )
            gout(n*9+1) = gout(n*9+1) + ( - s(27) - s(31) - s(35) )
            gout(n*9+2) = gout(n*9+2) + ( - s(54) - s(58) - s(62) )
            gout(n*9+3) = gout(n*9+3) + ( - s(9) - s(13) - s(17) )
            gout(n*9+4) = gout(n*9+4) + ( - s(36) - s(40) - s(44) )
            gout(n*9+5) = gout(n*9+5) + ( - s(63) - s(67) - s(71) )
            gout(n*9+6) = gout(n*9+6) + ( - s(18) - s(22) - s(26) )
            gout(n*9+7) = gout(n*9+7) + ( - s(45) - s(49) - s(53) )
            gout(n*9+8) = gout(n*9+8) + ( - s(72) - s(76) - s(80) )
         end if
      end do
   end subroutine CINTgout1e_int1e_ipipkin

