   subroutine CINTgout1e_int1e_ipkinip(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, ix, iy, iz, n
      integer  :: g0, g1, g2, g3, g4, g5, g6, g7
      integer  :: g8, g9, g10, g11, g12, g13, g14, g15
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:), g8p(:), g9p(:), g10p(:), g11p(:)
      real(dp), pointer, contiguous :: g12p(:), g13p(:), g14p(:), g15p(:)
      real(dp) :: s(0:80)

      nf = envs%nf
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
      g6 = g5 + envs%g_size * 3
      g7 = g6 + envs%g_size * 3
      g8 = g7 + envs%g_size * 3
      g9 = g8 + envs%g_size * 3
      g10 = g9 + envs%g_size * 3
      g11 = g10 + envs%g_size * 3
      g12 = g11 + envs%g_size * 3
      g13 = g12 + envs%g_size * 3
      g14 = g13 + envs%g_size * 3
      g15 = g14 + envs%g_size * 3
      call cint_nabla1j_1e(g, g1, g0, envs%i_l+1, envs%j_l+0, 0, envs)
      call cint_nabla1j_1e(g, g2, g0, envs%i_l+1, envs%j_l+1, 0, envs)
      call cint_nabla1j_1e(g, g3, g2, envs%i_l+1, envs%j_l+0, 0, envs)
      call cint_nabla1j_1e(g, g4, g0, envs%i_l+1, envs%j_l+2, 0, envs)
      call cint_nabla1j_1e(g, g5, g4, envs%i_l+1, envs%j_l+0, 0, envs)
      call cint_nabla1j_1e(g, g6, g4, envs%i_l+1, envs%j_l+1, 0, envs)
      call cint_nabla1j_1e(g, g7, g6, envs%i_l+1, envs%j_l+0, 0, envs)
      call cint_nabla1i_1e(g, g8, g0, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g9, g1, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g10, g2, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g11, g3, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g12, g4, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g13, g5, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g14, g6, envs%i_l+0, envs%j_l, 0, envs)
      call cint_nabla1i_1e(g, g15, g7, envs%i_l+0, envs%j_l, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)
      g4p(0:) => g(g4:)
      g5p(0:) => g(g5:)
      g6p(0:) => g(g6:)
      g7p(0:) => g(g7:)
      g8p(0:) => g(g8:)
      g9p(0:) => g(g9:)
      g10p(0:) => g(g10:)
      g11p(0:) => g(g11:)
      g12p(0:) => g(g12:)
      g13p(0:) => g(g13:)
      g14p(0:) => g(g14:)
      g15p(0:) => g(g15:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s(0) = + g15p(ix+0)*g0p(iy+0)*g0p(iz+0)
         s(1) = + g14p(ix+0)*g1p(iy+0)*g0p(iz+0)
         s(2) = + g14p(ix+0)*g0p(iy+0)*g1p(iz+0)
         s(3) = + g13p(ix+0)*g2p(iy+0)*g0p(iz+0)
         s(4) = + g12p(ix+0)*g3p(iy+0)*g0p(iz+0)
         s(5) = + g12p(ix+0)*g2p(iy+0)*g1p(iz+0)
         s(6) = + g13p(ix+0)*g0p(iy+0)*g2p(iz+0)
         s(7) = + g12p(ix+0)*g1p(iy+0)*g2p(iz+0)
         s(8) = + g12p(ix+0)*g0p(iy+0)*g3p(iz+0)
         s(9) = + g11p(ix+0)*g4p(iy+0)*g0p(iz+0)
         s(10) = + g10p(ix+0)*g5p(iy+0)*g0p(iz+0)
         s(11) = + g10p(ix+0)*g4p(iy+0)*g1p(iz+0)
         s(12) = + g9p(ix+0)*g6p(iy+0)*g0p(iz+0)
         s(13) = + g8p(ix+0)*g7p(iy+0)*g0p(iz+0)
         s(14) = + g8p(ix+0)*g6p(iy+0)*g1p(iz+0)
         s(15) = + g9p(ix+0)*g4p(iy+0)*g2p(iz+0)
         s(16) = + g8p(ix+0)*g5p(iy+0)*g2p(iz+0)
         s(17) = + g8p(ix+0)*g4p(iy+0)*g3p(iz+0)
         s(18) = + g11p(ix+0)*g0p(iy+0)*g4p(iz+0)
         s(19) = + g10p(ix+0)*g1p(iy+0)*g4p(iz+0)
         s(20) = + g10p(ix+0)*g0p(iy+0)*g5p(iz+0)
         s(21) = + g9p(ix+0)*g2p(iy+0)*g4p(iz+0)
         s(22) = + g8p(ix+0)*g3p(iy+0)*g4p(iz+0)
         s(23) = + g8p(ix+0)*g2p(iy+0)*g5p(iz+0)
         s(24) = + g9p(ix+0)*g0p(iy+0)*g6p(iz+0)
         s(25) = + g8p(ix+0)*g1p(iy+0)*g6p(iz+0)
         s(26) = + g8p(ix+0)*g0p(iy+0)*g7p(iz+0)
         s(27) = + g7p(ix+0)*g8p(iy+0)*g0p(iz+0)
         s(28) = + g6p(ix+0)*g9p(iy+0)*g0p(iz+0)
         s(29) = + g6p(ix+0)*g8p(iy+0)*g1p(iz+0)
         s(30) = + g5p(ix+0)*g10p(iy+0)*g0p(iz+0)
         s(31) = + g4p(ix+0)*g11p(iy+0)*g0p(iz+0)
         s(32) = + g4p(ix+0)*g10p(iy+0)*g1p(iz+0)
         s(33) = + g5p(ix+0)*g8p(iy+0)*g2p(iz+0)
         s(34) = + g4p(ix+0)*g9p(iy+0)*g2p(iz+0)
         s(35) = + g4p(ix+0)*g8p(iy+0)*g3p(iz+0)
         s(36) = + g3p(ix+0)*g12p(iy+0)*g0p(iz+0)
         s(37) = + g2p(ix+0)*g13p(iy+0)*g0p(iz+0)
         s(38) = + g2p(ix+0)*g12p(iy+0)*g1p(iz+0)
         s(39) = + g1p(ix+0)*g14p(iy+0)*g0p(iz+0)
         s(40) = + g0p(ix+0)*g15p(iy+0)*g0p(iz+0)
         s(41) = + g0p(ix+0)*g14p(iy+0)*g1p(iz+0)
         s(42) = + g1p(ix+0)*g12p(iy+0)*g2p(iz+0)
         s(43) = + g0p(ix+0)*g13p(iy+0)*g2p(iz+0)
