   subroutine CINTgout1e_int1e_ipprinvpip(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, nroots, ix, iy, iz, i, n
      integer  :: g0, g1, g2, g3, g4, g5, g6, g7
      integer  :: g8, g9, g10, g11, g12, g13, g14, g15
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:), g8p(:), g9p(:), g10p(:), g11p(:)
      real(dp), pointer, contiguous :: g12p(:), g13p(:), g14p(:), g15p(:)
      real(dp) :: s(0:80)

      nf = envs%nf
      nroots = envs%nrys_roots
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
      g6 = g5 + envs%g_size * 3
      g7 = g6 + envs%g_size * 3
      g8 = g7 + envs%g_size * 3
      g9 = g8 + envs%g_size * 3
      g10 = g9 + envs%g_size * 3
      g11 = g10 + envs%g_size * 3
      g12 = g11 + envs%g_size * 3
      g13 = g12 + envs%g_size * 3
      g14 = g13 + envs%g_size * 3
      g15 = g14 + envs%g_size * 3
      call cint_nabla1j_2e(g, g1, g0, envs%i_l+2, envs%j_l+0, 0, 0, envs)
      call cint_nabla1j_2e(g, g2, g0, envs%i_l+2, envs%j_l+1, 0, 0, envs)
      call cint_nabla1j_2e(g, g3, g2, envs%i_l+2, envs%j_l+0, 0, 0, envs)
      call cint_nabla1i_2e(g, g4, g0, envs%i_l+1, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g5, g1, envs%i_l+1, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g6, g2, envs%i_l+1, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g7, g3, envs%i_l+1, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g8, g0, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g9, g1, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g10, g2, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g11, g3, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g12, g4, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g13, g5, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g14, g6, envs%i_l+0, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g15, g7, envs%i_l+0, envs%j_l, 0, 0, envs)
      g0p(0:) => g(g0:)
      g1p(0:) => g(g1:)
      g2p(0:) => g(g2:)
      g3p(0:) => g(g3:)
      g4p(0:) => g(g4:)
      g5p(0:) => g(g5:)
      g6p(0:) => g(g6:)
      g7p(0:) => g(g7:)
      g8p(0:) => g(g8:)
      g9p(0:) => g(g9:)
      g10p(0:) => g(g10:)
      g11p(0:) => g(g11:)
      g12p(0:) => g(g12:)
      g13p(0:) => g(g13:)
      g14p(0:) => g(g14:)
      g15p(0:) => g(g15:)

      do n = 0, nf - 1
         ix = idx(0+n*3)
         iy = idx(1+n*3)
         iz = idx(2+n*3)
         s = 0.0_dp
         do i = 0, nroots - 1
               s(0) = s(0) + g15p(ix+i) * g0p(iy+i) * g0p(iz+i)
               s(1) = s(1) + g14p(ix+i) * g1p(iy+i) * g0p(iz+i)
               s(2) = s(2) + g14p(ix+i) * g0p(iy+i) * g1p(iz+i)
               s(3) = s(3) + g13p(ix+i) * g2p(iy+i) * g0p(iz+i)
               s(4) = s(4) + g12p(ix+i) * g3p(iy+i) * g0p(iz+i)
               s(5) = s(5) + g12p(ix+i) * g2p(iy+i) * g1p(iz+i)
               s(6) = s(6) + g13p(ix+i) * g0p(iy+i) * g2p(iz+i)
               s(7) = s(7) + g12p(ix+i) * g1p(iy+i) * g2p(iz+i)
               s(8) = s(8) + g12p(ix+i) * g0p(iy+i) * g3p(iz+i)
               s(9) = s(9) + g11p(ix+i) * g4p(iy+i) * g0p(iz+i)
               s(10) = s(10) + g10p(ix+i) * g5p(iy+i) * g0p(iz+i)
               s(11) = s(11) + g10p(ix+i) * g4p(iy+i) * g1p(iz+i)
               s(12) = s(12) + g9p(ix+i) * g6p(iy+i) * g0p(iz+i)
               s(13) = s(13) + g8p(ix+i) * g7p(iy+i) * g0p(iz+i)
               s(14) = s(14) + g8p(ix+i) * g6p(iy+i) * g1p(iz+i)
               s(15) = s(15) + g9p(ix+i) * g4p(iy+i) * g2p(iz+i)
               s(16) = s(16) + g8p(ix+i) * g5p(iy+i) * g2p(iz+i)
               s(17) = s(17) + g8p(ix+i) * g4p(iy+i) * g3p(iz+i)
               s(18) = s(18) + g11p(ix+i) * g0p(iy+i) * g4p(iz+i)
               s(19) = s(19) + g10p(ix+i) * g1p(iy+i) * g4p(iz+i)
               s(20) = s(20) + g10p(ix+i) * g0p(iy+i) * g5p(iz+i)
               s(21) = s(21) + g9p(ix+i) * g2p(iy+i) * g4p(iz+i)
               s(22) = s(22) + g8p(ix+i) * g3p(iy+i) * g4p(iz+i)
               s(23) = s(23) + g8p(ix+i) * g2p(iy+i) * g5p(iz+i)
               s(24) = s(24) + g9p(ix+i) * g0p(iy+i) * g6p(iz+i)
               s(25) = s(25) + g8p(ix+i) * g1p(iy+i) * g6p(iz+i)
               s(26) = s(26) + g8p(ix+i) * g0p(iy+i) * g7p(iz+i)
               s(27) = s(27) + g7p(ix+i) * g8p(iy+i) * g0p(iz+i)
               s(28) = s(28) + g6p(ix+i) * g9p(iy+i) * g0p(iz+i)
               s(29) = s(29) + g6p(ix+i) * g8p(iy+i) * g1p(iz+i)
               s(30) = s(30) + g5p(ix+i) * g10p(iy+i) * g0p(iz+i)
               s(31) = s(31) + g4p(ix+i) * g11p(iy+i) * g0p(iz+i)
               s(32) = s(32) + g4p(ix+i) * g10p(iy+i) * g1p(iz+i)
               s(33) = s(33) + g5p(ix+i) * g8p(iy+i) * g2p(iz+i)
               s(34) = s(34) + g4p(ix+i) * g9p(iy+i) * g2p(iz+i)
               s(35) = s(35) + g4p(ix+i) * g8p(iy+i) * g3p(iz+i)
               s(36) = s(36) + g3p(ix+i) * g12p(iy+i) * g0p(iz+i)
               s(37) = s(37) + g2p(ix+i) * g13p(iy+i) * g0p(iz+i)
               s(38) = s(38) + g2p(ix+i) * g12p(iy+i) * g1p(iz+i)
               s(39) = s(39) + g1p(ix+i) * g14p(iy+i) * g0p(iz+i)
               s(40) = s(40) + g0p(ix+i) * g15p(iy+i) * g0p(iz+i)
               s(41) = s(41) + g0p(ix+i) * g14p(iy+i) * g1p(iz+i)
               s(42) = s(42) + g1p(ix+i) * g12p(iy+i) * g2p(iz+i)
               s(43) = s(43) + g0p(ix+i) * g13p(iy+i) * g2p(iz+i)
               s(44) = s(44) + g0p(ix+i) * g12p(iy+i) * g3p(iz+i)
               s(45) = s(45) + g3p(ix+i) * g8p(iy+i) * g4p(iz+i)
               s(46) = s(46) + g2p(ix+i) * g9p(iy+i) * g4p(iz+i)
               s(47) = s(47) + g2p(ix+i) * g8p(iy+i) * g5p(iz+i)
               s(48) = s(48) + g1p(ix+i) * g10p(iy+i) * g4p(iz+i)
               s(49) = s(49) + g0p(ix+i) * g11p(iy+i) * g4p(iz+i)
               s(50) = s(50) + g0p(ix+i) * g10p(iy+i) * g5p(iz+i)
               s(51) = s(51) + g1p(ix+i) * g8p(iy+i) * g6p(iz+i)
               s(52) = s(52) + g0p(ix+i) * g9p(iy+i) * g6p(iz+i)
               s(53) = s(53) + g0p(ix+i) * g8p(iy+i) * g7p(iz+i)
               s(54) = s(54) + g7p(ix+i) * g0p(iy+i) * g8p(iz+i)
               s(55) = s(55) + g6p(ix+i) * g1p(iy+i) * g8p(iz+i)
               s(56) = s(56) + g6p(ix+i) * g0p(iy+i) * g9p(iz+i)
               s(57) = s(57) + g5p(ix+i) * g2p(iy+i) * g8p(iz+i)
               s(58) = s(58) + g4p(ix+i) * g3p(iy+i) * g8p(iz+i)
               s(59) = s(59) + g4p(ix+i) * g2p(iy+i) * g9p(iz+i)
               s(60) = s(60) + g5p(ix+i) * g0p(iy+i) * g10p(iz+i)
               s(61) = s(61) + g4p(ix+i) * g1p(iy+i) * g10p(iz+i)
               s(62) = s(62) + g4p(ix+i) * g0p(iy+i) * g11p(iz+i)
               s(63) = s(63) + g3p(ix+i) * g4p(iy+i) * g8p(iz+i)
               s(64) = s(64) + g2p(ix+i) * g5p(iy+i) * g8p(iz+i)
               s(65) = s(65) + g2p(ix+i) * g4p(iy+i) * g9p(iz+i)
               s(66) = s(66) + g1p(ix+i) * g6p(iy+i) * g8p(iz+i)
               s(67) = s(67) + g0p(ix+i) * g7p(iy+i) * g8p(iz+i)
               s(68) = s(68) + g0p(ix+i) * g6p(iy+i) * g9p(iz+i)
               s(69) = s(69) + g1p(ix+i) * g4p(iy+i) * g10p(iz+i)
               s(70) = s(70) + g0p(ix+i) * g5p(iy+i) * g10p(iz+i)
               s(71) = s(71) + g0p(ix+i) * g4p(iy+i) * g11p(iz+i)
               s(72) = s(72) + g3p(ix+i) * g0p(iy+i) * g12p(iz+i)
               s(73) = s(73) + g2p(ix+i) * g1p(iy+i) * g12p(iz+i)
               s(74) = s(74) + g2p(ix+i) * g0p(iy+i) * g13p(iz+i)
               s(75) = s(75) + g1p(ix+i) * g2p(iy+i) * g12p(iz+i)
               s(76) = s(76) + g0p(ix+i) * g3p(iy+i) * g12p(iz+i)
               s(77) = s(77) + g0p(ix+i) * g2p(iy+i) * g13p(iz+i)
               s(78) = s(78) + g1p(ix+i) * g0p(iy+i) * g14p(iz+i)
               s(79) = s(79) + g0p(ix+i) * g1p(iy+i) * g14p(iz+i)
               s(80) = s(80) + g0p(ix+i) * g0p(iy+i) * g15p(iz+i)
         end do
         if (gout_empty /= 0) then
            gout(n*9+0) = + s(0) + s(12) + s(24)
            gout(n*9+1) = + s(27) + s(39) + s(51)
            gout(n*9+2) = + s(54) + s(66) + s(78)
            gout(n*9+3) = + s(1) + s(13) + s(25)
            gout(n*9+4) = + s(28) + s(40) + s(52)
            gout(n*9+5) = + s(55) + s(67) + s(79)
            gout(n*9+6) = + s(2) + s(14) + s(26)
            gout(n*9+7) = + s(29) + s(41) + s(53)
            gout(n*9+8) = + s(56) + s(68) + s(80)
         else
            gout(n*9+0) = gout(n*9+0) + ( + s(0) + s(12) + s(24) )
            gout(n*9+1) = gout(n*9+1) + ( + s(27) + s(39) + s(51) )
            gout(n*9+2) = gout(n*9+2) + ( + s(54) + s(66) + s(78) )
            gout(n*9+3) = gout(n*9+3) + ( + s(1) + s(13) + s(25) )
            gout(n*9+4) = gout(n*9+4) + ( + s(28) + s(40) + s(52) )
            gout(n*9+5) = gout(n*9+5) + ( + s(55) + s(67) + s(79) )
