   subroutine CINTgout1e_int1e_ipipspnucsp(gout, g, idx, envs, gout_empty)
      real(dp), intent(inout) :: gout(0:*)
      real(dp), intent(inout), target :: g(0:)
      integer,  intent(in)    :: idx(0:*)
      type(cint_env_vars), intent(in) :: envs
      integer,  intent(in)    :: gout_empty
      integer  :: nf, nroots, ix, iy, iz, i, n
      integer  :: g0, g1, g2, g3, g4, g5, g6, g7
      integer  :: g8, g9, g10, g11, g12, g13, g14, g15
      real(dp), pointer, contiguous :: g0p(:), g1p(:), g2p(:), g3p(:), g4p(:), g5p(:)
      real(dp), pointer, contiguous :: g6p(:), g7p(:), g8p(:), g9p(:), g10p(:), g11p(:)
      real(dp), pointer, contiguous :: g12p(:), g13p(:), g14p(:), g15p(:)
      real(dp) :: s(0:80)

      nf = envs%nf
      nroots = envs%nrys_roots
      g0 = 0
      g1 = g0 + envs%g_size * 3
      g2 = g1 + envs%g_size * 3
      g3 = g2 + envs%g_size * 3
      g4 = g3 + envs%g_size * 3
      g5 = g4 + envs%g_size * 3
      g6 = g5 + envs%g_size * 3
      g7 = g6 + envs%g_size * 3
      g8 = g7 + envs%g_size * 3
      g9 = g8 + envs%g_size * 3
      g10 = g9 + envs%g_size * 3
      g11 = g10 + envs%g_size * 3
      g12 = g11 + envs%g_size * 3
      g13 = g12 + envs%g_size * 3
      g14 = g13 + envs%g_size * 3
      g15 = g14 + envs%g_size * 3
      call cint_nabla1j_2e(g, g1, g0, envs%i_l+3, envs%j_l+0, 0, 0, envs)
      call cint_nabla1i_2e(g, g2, g0, envs%i_l+2, envs%j_l, 0, 0, envs)
      call cint_nabla1i_2e(g, g3, g1, envs%i_l+2, envs%j_l, 0, 0, envs)
