      g14 = g13 + envs%g_size * 3
      g15 = g14 + envs%g_size * 3
      call cint_nabla1j_2e(g, g1, g0, envs%i_l+2, envs%j_l+0, 0, 0, envs)
      call cint_nabla1j_2e(g, g2, g0, envs%i_l+2, envs%j_l+1, 0, 0, envs)
      call cint_nabla1j_2e(g, g3, g2, envs%i_l+2, envs%j_l+0, 0, 0, envs)
